const items = $input.all();
if (items.length !== 1) throw new Error('INVALID_REPORT_COUNT');
const r = items[0].json;
const keys = ['schema', 'total', 'candidates', 'rejected', 'status',
  'source_authorized', 'independently_verified', 'eligible_for_model_scoring',
  'production_recommendations', 'external_calls', 'corroboration_executed'];
if (!r || typeof r !== 'object' || Array.isArray(r) ||
    Object.keys(r).length !== keys.length ||
    !keys.every(k => Object.prototype.hasOwnProperty.call(r, k)))
  throw new Error('UNEXPECTED_REPORT_FIELDS');
if (r.schema !== 'intelligence-x-offline-batch-v1' ||
    r.status !== 'HOLD' || r.production_recommendations !== 'DISABLED' ||
    r.source_authorized !== false || r.independently_verified !== false ||
    r.eligible_for_model_scoring !== false || r.external_calls !== 0 ||
    r.corroboration_executed !== false ||
    ![r.total, r.candidates, r.rejected].every(v => Number.isSafeInteger(v) && v >= 0 && v <= 32) ||
    r.candidates + r.rejected !== r.total)
  throw new Error('UNSAFE_OR_INVALID_REPORT');
return [{json: {
  schema: 'intelligence-x-n8n-offline-summary-v1',
  input_kind: 'SYNTHETIC_MANUAL_DEMO',
  total: r.total, candidates: r.candidates, rejected: r.rejected,
  alert: r.total === 0 ? 'EMPTY_BATCH' : r.rejected > 0 ? 'REJECTED_CAPTURE' : 'RESEARCH_ONLY',
  status: 'HOLD', source_authorized: false, independently_verified: false,
  eligible_for_model_scoring: false, production_recommendations: 'DISABLED',
  external_calls: 0
}}];
